def compute(vars):
    interest_and_penalties = vars["v1"]
    total_unrecognized_tax_benefits = vars["v2"]

    if total_unrecognized_tax_benefits == 0:
        return None

    ratio_percent = interest_and_penalties / total_unrecognized_tax_benefits * 100
    return {
        "value": ratio_percent,
        "trace": {
            "interest_and_penalties": interest_and_penalties,
            "total_unrecognized_tax_benefits": total_unrecognized_tax_benefits,
            "ratio_percent": ratio_percent,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
